node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// === 1. REMOVE HARBOR COTTON CREW TEE (CI-0023) ===
db.prepare(\"DELETE FROM cart_items WHERE cart_item_id = 'CI-0023'\").run();

// Update cart: remove CI-0023 from item_ids, recalculate
const cart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_d3d5d0c8'\").get();
const itemIds = JSON.parse(cart.item_ids_json).filter(id => id !== 'CI-0023');

// New subtotal = just the mouse at \$39
const newSubtotal = 39;

// === 2. SET EXPRESS SHIPPING (free for Gold) ===
const shippingOption = 'express';
const shippingCost = 0; // Free for Gold tier

// === 3. APPLY LOYALTY POINTS ===
// Policy: 100 points = \$1, cap at 50% of cart total, min 500 points
// Cart total for redemption calc = subtotal + gift_wrap_fee - discount_amount = 39 + 0 - 0 = 39
const cartTotalForCap = newSubtotal; // 39
const maxDiscount = Math.floor(cartTotalForCap * 0.5); // 19
const pointsToRedeem = maxDiscount * 100; // 1900 points

console.log('=== LOYALTY POINTS CALCULATION ===');
console.log('Cart subtotal: \$' + newSubtotal);
console.log('50% cap: \$' + maxDiscount);
console.log('Points to redeem: ' + pointsToRedeem + ' (= \$' + maxDiscount + ')');
console.log('Customer balance: 5623 points');
console.log('Remaining points after: ' + (5623 - pointsToRedeem));

// Update cart
const loyaltyDiscount = maxDiscount; // \$19
const loyaltyPointsRedeemed = pointsToRedeem; // 1900
const newTotal = newSubtotal - loyaltyDiscount + shippingCost; // 39 - 19 + 0 = 20

db.prepare(\`
  UPDATE carts SET 
    subtotal = ?, 
    discount_amount = 0,
    gift_wrap_fee = 0,
    loyalty_discount = ?,
    loyalty_points_redeemed = ?,
    shipping_option = ?,
    shipping_cost = ?,
    total = ?,
    item_ids_json = ?
  WHERE cart_id = 'CART-user_d3d5d0c8'
\`).run(newSubtotal, loyaltyDiscount, loyaltyPointsRedeemed, shippingOption, shippingCost, newTotal, JSON.stringify(itemIds));

// Debit loyalty points from customer
db.prepare(\"UPDATE users SET loyalty_points = loyalty_points - ? WHERE user_id = 'user_d3d5d0c8'\").run(pointsToRedeem);

console.log('\n=== FINAL CART STATE ===');
const updatedCart = db.prepare(\"SELECT * FROM carts WHERE cart_id = 'CART-user_d3d5d0c8'\").get();
console.log(JSON.stringify(updatedCart, null, 2));

const remainingItems = db.prepare(\"SELECT ci.*, p.name, p.price FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.cart_id = 'CART-user_d3d5d0c8'\").all();
console.log('\nCart items:');
remainingItems.forEach(i => console.log('  ', i.cart_item_id, i.name, '\$' + i.price, 'qty:', i.quantity));

const cust = db.prepare(\"SELECT loyalty_points, store_credit_balance FROM users WHERE user_id = 'user_d3d5d0c8'\").get();
console.log('\nCustomer loyalty points remaining:', cust.loyalty_points);
console.log('Customer store credit:', cust.store_credit_balance);
"
